"""Affine credit dynamics converge to c/(1-k) for 0<=k<1."""
from __future__ import annotations

def credit_iterate(c: float, k: float, x0: float, n: int) -> float:
    x = x0
    for _ in range(n):
        x = c + k * x
    return x

def equilibrium(c: float, k: float) -> float:
    return c / (1 - k)

if __name__ == "__main__":
    c, k = 0.4, 0.7
    star = equilibrium(c, k)
    print("equilibrium =", star)
    for x0 in (0.0, 5.0, -3.0):
        val = credit_iterate(c, k, x0, 300)
        print(f"x0={x0:+.1f} -> {val:.10f}  err={abs(val-star):.2e}")

"""Cantor verdict encoding: bounds, self-similarity, injectivity."""
from __future__ import annotations
from typing import List, Sequence

def cantor_encode(verdicts: Sequence[bool]) -> float:
    """Phi(a) = sum_n (2 if a_n else 0)/3^(n+1) over a finite prefix."""
    return sum((2.0 if a else 0.0) / 3.0 ** (n + 1) for n, a in enumerate(verdicts))

def cantor_decode(x: float, depth: int) -> List[bool]:
    """Invert the IFS: <1/3 -> False, x->3x; >=2/3 -> True, x->3x-2."""
    out: List[bool] = []
    for _ in range(depth):
        if x < 1/3:
            out.append(False); x = 3 * x
        elif x >= 2/3:
            out.append(True); x = 3 * x - 2
        else:
            raise ValueError(f"{x:.6f} lies in a gap: not in the Cantor set")
    return out

if __name__ == "__main__":
    a = [True, False, True, True, False, False, True]
    x = cantor_encode(a)
    print("score =", x)
    print("bounds  0 <= x <= 1 :", 0 <= x <= 1)
    # self-similarity
    print("Phi(false.a) == Phi(a)/3 :", abs(cantor_encode([False]+a) - x/3) < 1e-12)
    print("Phi(true .a) == Phi(a)/3+2/3 :", abs(cantor_encode([True]+a) - (x/3+2/3)) < 1e-12)
    print("decoded == a :", cantor_decode(x, len(a)) == a)

