from __future__ import annotations
from typing import Sequence, Tuple

def encode_with_error(verdicts: Sequence[bool]) -> Tuple[float, float]:
    """Truncated ternary credit score and rigorous absolute error bound.

    Returns (score, error) where the exact infinite score lies in
    [score, score + error] and error = 3^-N for N verdicts, since the tail
    sum_{n>=N} 2/3^(n+1) equals 3^-N.
    """
    score = 0.0
    for n, a in enumerate(verdicts):
        if a:
            score += 2.0 / 3.0 ** (n + 1)
    return score, 3.0 ** (-len(verdicts))

from __future__ import annotations
import math

def steps_to_equilibrium(c: float, k: float, x0: float, eps: float) -> int:
    """Number of affine updates x -> c + k*x needed for |x_n - c/(1-k)| < eps.

    Uses |x_n - x*| = k^n * |x0 - x*| with x* = c/(1-k); requires 0 <= k < 1.
    """
    if not (0.0 <= k < 1.0):
        raise ValueError("damping must satisfy 0 <= k < 1")
    star = c / (1.0 - k)
    gap = abs(x0 - star)
    if gap < eps or k == 0.0:
        return 0
    return math.ceil(math.log(eps / gap) / math.log(k))
